// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= 100 ether);
        vm.deal(address(this), amount);
        uint256 initialBalance = address(this).balance;
        c.deposit{value: amount}();
        uint256 contractBalanceAfterDeposit = address(c).balance;
        // migrateTo should transfer the full balance
        address to = address(0x1234);
        uint256 toBalanceBefore = to.balance;
        vm.prank(address(this));
        c.migrateTo(to);
        uint256 transferred = to.balance - toBalanceBefore;
        assertTrue(transferred == contractBalanceAfterDeposit, "Should transfer full balance");
    }
}

